    """ArgumentParser that always exits with status 2 on usage errors."""

    def error(self, message):  # pragma: no cover - same as argparse, explicit
        self.print_usage(sys.stderr)
        self.exit(EXIT_USAGE, f"{self.prog}: error: {message}\n")


def _date_arg(text: str):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = _ArgumentParser(
        prog="pennywise",
        description="Tell you where the money in a plain-text ledger went.",
    )
    sub = parser.add_subparsers(
        dest="command", metavar="COMMAND", parser_class=_ArgumentParser
    )
    sub.required = True

    file_help = "ledger file ('-' for standard input)"

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument(
        "--by", choices=("category", "month"), default="category",
        help="how to group entries (default: category)",
    )
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--category", metavar="C", help="only this category")
    p.add_argument("--since", metavar="DATE", type=_date_arg,
                   help="only entries on or after DATE (YYYY-MM-DD)")
    p.add_argument("--until", metavar="DATE", type=_date_arg,
                   help="only entries on or before DATE (YYYY-MM-DD)")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help=file_help)
    p.add_argument("--format", choices=("csv",), default="csv",
                   help="output format (default: csv)")
    return parser


def _read_text(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as fh:
                data = fh.read()
        return data.decode("utf-8-sig")
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        raise _CannotRead(f"cannot read {name}: {_describe(exc)}") from None


def _describe(exc: Exception) -> str:
    if isinstance(exc, OSError) and exc.strerror:
        return exc.strerror
    if isinstance(exc, UnicodeDecodeError):
        return "not valid UTF-8 text"
    return str(exc)


def _load(path: str) -> List[Entry]:
    return parse(_read_text(path))


def _chronological(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: ties keep file order


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args, out) -> int:
    total = format_amount(balance(_load(args.file)))
    if args.json:
        out.write(json.dumps({"balance": total}) + "\n")
    else:
        out.write(total + "\n")
    return EXIT_OK


def _cmd_summary(args, out) -> int:
    entries = _load(args.file)
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(groups)
    if args.json:
        data = {name: format_amount(groups[name]) for name in names}
        out.write(json.dumps(data) + "\n")
    else:
        out.write("".join(f"{n}  {format_amount(groups[n])}\n" for n in names))
    return EXIT_OK


def _cmd_list(args, out) -> int:
    entries = filter_entries(
        _load(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = _chronological(entries)
    if args.json:
        out.write(json.dumps([_entry_dict(e) for e in entries]) + "\n")
    else:
        out.write("".join(format_entry(e) + "\n" for e in entries))
    return EXIT_OK


def _cmd_export(args, out) -> int:
    entries = _chronological(_load(args.file))
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow(
            [e.date.isoformat(), e.category, format_amount(e.amount), e.note]
        )
    return EXIT_OK


def _cmd_add(args, out) -> int:
    path = args.file
    try:
        with open(path, "rb") as fh:
            existing = fh.read()
    except FileNotFoundError:
        existing = None
    except OSError as exc:
        raise _CannotRead(f"cannot read {path}: {_describe(exc)}") from None

    if existing:
        try:
            text = existing.decode("utf-8-sig")
        except UnicodeDecodeError:
            raise _CannotRead(f"cannot read {path}: not valid UTF-8 text") from None
        needs_newline = not text.endswith("\n")
        line_no = text.count("\n") + 1 + (1 if needs_newline else 0)
        if text.endswith("\n"):
            line_no = text.count("\n") + 1
    else:
        needs_newline = False
        line_no = 1

    note = args.note
    if any(c in note for c in "\r\n"):
        raise ParseError(line_no, "note must be on a single line")
    raw = " ".join([args.date, args.category, args.amount] + ([note] if note.strip() else []))
    if any(c in raw for c in "\r\n"):
        raise ParseError(line_no, "entry must be on a single line")
    if any(c.isspace() for c in args.category) or not args.category:
        raise ParseError(line_no, f"invalid category {args.category!r} (expected one word)")
    if args.date.lstrip().startswith("#"):
        raise ParseError(line_no, f"invalid date {args.date!r} (expected YYYY-MM-DD)")
    entry = parse_line(raw, line_no)
    if entry is None:  # e.g. everything blank
        raise ParseError(line_no, "expected 'DATE CATEGORY AMOUNT [NOTE]'")
    # Fields must be exactly what the user passed (no hidden extra fields).
    if entry.date.isoformat() != args.date or entry.note != note.strip():
        raise ParseError(line_no, "invalid entry")

    line = format_entry(entry)
    try:
        with open(path, "a", encoding="utf-8", newline="") as fh:
            fh.write(("\n" if needs_newline else "") + line + "\n")
    except OSError as exc:
        raise _CannotRead(f"cannot write {path}: {_describe(exc)}") from None
    out.write(line + "\n")
    return EXIT_OK


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else EXIT_USAGE

    out = sys.stdout
    try:
        status = _COMMANDS[args.command](args, out)
        out.flush()
        return status
    except ParseError as exc:
        where = "standard input" if args.file == "-" else args.file
        sys.stderr.write(f"pennywise: {where}: {exc}\n")
        return EXIT_LEDGER
    except _CannotRead as exc:
        sys.stderr.write(f"pennywise: {exc}\n")
        return EXIT_USAGE
    except BrokenPipeError:
        try:
            sys.stdout = None  # type: ignore[assignment]
        finally:
            os.dup2(os.open(os.devnull, os.O_WRONLY), 1)
        return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
