            raise _CannotRead(f"cannot read {path}: not valid UTF-8 text") from None
    else:
        text = ""
    needs_newline = bool(text) and not text.endswith("\n")
    # The number the new line will have in the file, for error messages.
    line_no = text.count("\n") + (2 if needs_newline else 1)

    try:
        date = parse_date(args.date)
        category = _check_category(args.category)
        amount = parse_amount(args.amount)
        note = _check_note(args.note)
    except ValueError as exc:
        raise ParseError(line_no, str(exc)) from None
    entry = Entry(date, category, amount, note)
    line = format_entry(entry)
    try:
        with open(path, "a", encoding="utf-8", newline="") as fh:
            fh.write(("\n" if needs_newline else "") + line + "\n")
    except OSError as exc:
        raise _CannotRead(f"cannot write {path}: {_describe(exc)}") from None
    out.write(line + "\n")
    return EXIT_OK


